// Package certificate defines the records of client certificates issued to
// users, which the users and the operators managing them may revoke.
package certificate

import (
	"errors"
	"time"
)

// KeySource tells where the certificate's private key was created.
type KeySource string

// The key sources.
const (
	// KeySourceGenerated is a key generated by the server and downloaded once by the user.
	KeySourceGenerated KeySource = "generated"
	// KeySourceCSR is a key kept by the user, who sent a certificate signing request.
	KeySourceCSR KeySource = "csr"
)

// MaxList bounds the number of certificates one list returns.
const MaxList = 200

var (
	// ErrNotFound is returned when there is no certificate with the given serial.
	ErrNotFound = errors.New("certificate not found")
	// ErrRevoked is returned when revoking a certificate that is already revoked.
	ErrRevoked = errors.New("certificate already revoked")
)

// Certificate is the record of one issued certificate.
type Certificate struct {
	// Serial is the lowercase hex serial number.
	Serial string `json:"serial"`
	// UserPK is the authentik primary key of the user the certificate is issued to.
	UserPK   int    `json:"user_pk"`
	Username string `json:"username"`
	// Subject is the certificate's subject distinguished name.
	Subject   string    `json:"subject"`
	NotBefore time.Time `json:"not_before"`
	NotAfter  time.Time `json:"not_after"`
	// IssuedAt is set by the store.
	IssuedAt time.Time `json:"issued_at"`
	// IssuedBy is the username of the user who requested the certificate.
	IssuedBy  string    `json:"issued_by"`
	KeySource KeySource `json:"key_source"`
	// RevokedAt is nil while the certificate is not revoked.
	RevokedAt *time.Time `json:"revoked_at"`
	// RevokedBy is the username of the revoking user; empty while not revoked.
	RevokedBy string `json:"revoked_by"`
}

// Revoked is a revoked certificate, as listed in the CRL.
type Revoked struct {
	Serial    string
	RevokedAt time.Time
}
